var KAPRoomsFilteredBasedOnAvailabilityOfStartEnd = Class.create();
KAPRoomsFilteredBasedOnAvailabilityOfStartEnd.prototype = {
    initialize: function () { },

    getAvailableRoomsQuery: function (startDate, endDate) {
        var availableRooms = [];

        // Convert to GlideDateTime
        var start = new GlideDateTime(startDate);
        var end = new GlideDateTime(endDate);

        // Step 1: Get all rooms
        var roomGR = new GlideRecord('x_1809800_event_0_event_room');
        roomGR.query();
        while (roomGR.next()) {
            availableRooms.push(roomGR.sys_id.toString());
        }

        // Step 2: Exclude rooms that have bookings overlapping with this time
        var bookingGR = new GlideRecord('x_1809800_event_0_event_booking');
        bookingGR.addQuery('start_date', '<=', end);
        bookingGR.addQuery('end_date', '>=', start);
        bookingGR.addQuery('status', '!=', 'cancelled');
        bookingGR.query();
        while (bookingGR.next()) {
            var bookedRoomId = bookingGR.room.sys_id.toString();
            var index = availableRooms.indexOf(bookedRoomId);
            if (index !== -1) {
                availableRooms.splice(index, 1);
            }
        }

        // Step 3: Exclude rooms under maintenance during this time
        var maintGR = new GlideRecord('x_1809800_event_0_room_maintenance');
        //maintGR.addQuery('status', 'under_maintenance');
        maintGR.addQuery('start_datetime', '<=', end); // overlaps end
        maintGR.addQuery('end_datetime', '>=', start); // overlaps start
        maintGR.query();
        while (maintGR.next()) {
            var maintainedRoomId = maintGR.room.sys_id.toString();
            var ind = availableRooms.indexOf(maintainedRoomId);
            if (ind !== -1) {
                availableRooms.splice(ind, 1);
            }
        }

        return 'sys_idIN' + availableRooms.join(',');
    },

    type: 'KAPRoomsFilteredBasedOnAvailabilityOfStartEnd'
};
